&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de moine&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_moine_0&quot; href=&quot;#Les_arch&#233;types_de_moine_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-Des-Armes-(Moine).html&quot; title=&quot;Adepte des armes&quot;&gt;Adepte des armes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-Du-Feu-Serpent-(Moine).html&quot; title=&quot;Adepte du feu-serpent&quot;&gt;Adepte du feu-serpent&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-Zen-(Moine).html&quot; title=&quot;Archer zen&quot;&gt;Archer zen&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artiste-Martial-(Moine).html&quot; title=&quot;Artiste martial&quot;&gt;Artiste martial&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aspic-Noir-(Moine).html&quot; title=&quot;Aspic noir&quot;&gt;Aspic noir&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Des-Poids-Plume-(Moine).html&quot; title=&quot;Champion des poids plume&quot;&gt;Champion des poids plume&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html&quot; title=&quot;Les halfelins&quot;&gt;Halfelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chat-Sauvage-(Moine).html&quot; title=&quot;Chat sauvage&quot;&gt;Chat sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Disciple-Gris-(Moine).html&quot; title=&quot;Disciple gris&quot;&gt;Disciple gris&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Duergar-(Race).html&quot; title=&quot;Les duergars&quot;&gt;Duergar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;l&#232;ve-De-La-Pierre-(Moine).html&quot; title=&quot;&#201;l&#232;ve de la pierre&quot;&gt;&#201;l&#232;ve de la pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;Or&#233;ade&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Agile-(Moine).html&quot; title=&quot;Gardien agile&quot;&gt;Gardien agile&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-F&#233;lin-(Race).html&quot; title=&quot;Les hommes-f&#233;lins&quot;&gt;Homme-f&#233;lin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-&#201;coles-(Moine).html&quot; title=&quot;Ma&#238;tre des &#233;coles&quot;&gt;Ma&#238;tre des &#233;coles&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Katas-(Moine).html&quot; title=&quot;Ma&#238;tre des katas&quot;&gt;Ma&#238;tre des katas&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Manoeuvres-(Moine).html&quot; title=&quot;Ma&#238;tre des manoeuvres&quot;&gt;Ma&#238;tre des manœuvres&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Ivre-(Moine).html&quot; title=&quot;Ma&#238;tre ivre&quot;&gt;Ma&#238;tre ivre&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-&#192;-Peau-De-Fer-(Moine).html&quot; title=&quot;Moine &#224; peau de fer&quot;&gt;Moine &#224; peau de fer&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;Hobgobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Main-Qui-Gu&#233;rit-(Moine).html&quot; title=&quot;Moine de la main qui gu&#233;rit&quot;&gt; Moine de la main qui gu&#233;rit&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Main-Vide-(Moine).html&quot; title=&quot;Moine de la main vide&quot;&gt;Moine de la main vide&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Montagne-Sacr&#233;e-(Moine).html&quot; title=&quot;Moine de la montagne sacr&#233;e&quot;&gt;Moine de la montagne sacr&#233;e&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Des-Cimes-(Moine).html&quot; title=&quot;Moine des cimes&quot;&gt;Moine des cimes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vanara-(Race).html&quot; title=&quot;Les vanaras&quot;&gt;Vanara&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Des-Quatre-Vents-(Moine).html&quot; title=&quot;Moine des quatre vents&quot;&gt;Moine des quatre vents&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Du-Fant&#244;me-Affam&#233;-(Moine).html&quot; title=&quot;Moine du fant&#244;me affam&#233;&quot;&gt; Moine du fant&#244;me affam&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Du-Lotus-(Moine).html&quot; title=&quot;Moine du lotus&quot;&gt;Moine du lotus&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Fluide-(Moine).html&quot; title=&quot;Moine fluide&quot;&gt;Moine fluide&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Karmique-(Moine).html&quot; title=&quot;Moine karmique&quot;&gt;Moine karmique&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Qinggong-(Moine).html&quot; title=&quot;Moine qinggong&quot;&gt;Moine qinggong&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mystique-Ki-(Moine).html&quot; title=&quot;Mystique ki&quot;&gt;Mystique ki&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Conseiller-(Moine).html&quot; title=&quot;Sage conseiller&quot;&gt;Sage conseiller&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sensei-(Moine).html&quot; title=&quot;Sensei&quot;&gt;Sensei&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sohei-(Moine).html&quot; title=&quot;Sohei&quot;&gt;Sohei&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tetori-(Moine).html&quot; title=&quot;Tetori&quot;&gt;Tetori&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vagabond-(Moine).html&quot; title=&quot;Vagabond&quot;&gt;Vagabond&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Les mystiques &lt;/i&gt;ki&lt;i&gt; pensent que la violence est parfois n&#233;cessaire mais que la connaissance et la compr&#233;hension sont les v&#233;ritables clefs de la perfection. &#192; travers leurs m&#233;ditations et leurs visions spirituelles, ils peuvent percer le voile de la r&#233;alit&#233; pour scruter les v&#233;rit&#233;s qui sous-tendent toute chose.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Le mystique ki poss&#232;de les capacit&#233;s suivantes.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mystique ki (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Mystique_ki_Sur_0&quot; href=&quot;#Mystique_ki_Sur_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;u&gt;Ce texte a &#233;t&#233; modifi&#233; suite &#224; la FAQ suivante :&lt;/u&gt;&lt;br /&gt;&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Manuel-Des-Joueurs---R&#232;gles-Avanc&#233;es.html#31&quot; title=&quot;FAQ du Manuel des joueurs - R&#232;gles avanc&#233;es&quot;&gt;→&lt;/a&gt; Moine, Mystique ki : La capacit&#233; mystique ki semble modifier la capacit&#233; de moine r&#233;serve de ki, hors elle n&#39;indique pas &#171; Cette capacit&#233; modifie r&#233;serve de ki. &#187;. Est-ce parce que la r&#233;serve de ki du mystique ki est une seconde r&#233;serve s&#233;par&#233;e qui n&#39;est utilis&#233;e que par les pouvoirs d&#233;crits dans l&#39;arch&#233;type et que le moine re&#231;oit &#233;galement une r&#233;serve de ki qui fonctionne normalement ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Non. Lorsque le &lt;i&gt;Manuel des joueurs - R&#232;gles avanc&#233;es&lt;/i&gt; a &#233;t&#233; &#233;crit, les arch&#233;types &#233;taient nouveaux et la formulation &#171; Cela modifie &#187; n&#39;existait pas encore, ce qui signifie que les arch&#233;types de cet ouvrage, y compris le &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mystique-Ki-(Moine).html&quot; title=&quot;Mystique ki&quot;&gt;mystique ki&lt;/a&gt;&lt;/u&gt;, ne l&#39;incluent pas, m&#234;me s&#39;ils devraient selon les standards actuels. La capacit&#233; mystique ki modifie r&#233;serve de ki. Au niveau 3, le mystique ki gagne une r&#233;serve de points de ki &#233;gale &#224; son modificateur de Sagesse qui peut &#234;tre utilis&#233;e dans le cadre des capacit&#233;s list&#233;es dans cet arch&#233;type. Cette r&#233;serve augmente jusqu&#39;&#224; atteindre la moiti&#233; de son niveau de moine + son modificateur de Sagesse + 2 au niveau 4, mais reste une unique r&#233;serve de ki (le mystique ki n&#39;en poss&#232;de pas deux) qui peut &#234;tre utilis&#233;e de la m&#234;me fa&#231;on que le ki d&#39;un moine classique, en plus de celles mentionn&#233;es dans l&#39;arch&#233;type.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;Au niveau 3, le mystique &lt;i&gt;ki&lt;/i&gt; gagne une &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#RESERVEDEKI&quot; title=&quot;Le moine&quot;&gt;r&#233;serve de points de ki&lt;/a&gt; &#233;gale &#224; son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt;. Cette r&#233;serve augmente jusqu’&#224; atteindre la moiti&#233; de son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; + 2 au niveau 4. Si le moine poss&#232;de au moins 1 point de ki dans sa r&#233;serve, il gagne un bonus de +2 &#224; tous les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Jettest.html&quot; title=&quot;test&quot;&gt;tests&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt;. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, le moine peut d&#233;penser 1 point de &lt;i&gt;ki&lt;/i&gt; juste avant d’effectuer un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Jettest.html&quot; title=&quot;test&quot;&gt;test&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques.html&quot; title=&quot;Les caract&#233;ristiques&quot;&gt;caract&#233;ristique&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt; afin de gagner un bonus d’intuition de +4. Cette capacit&#233; modifie &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#RESERVEDEKI&quot; title=&quot;Le moine&quot;&gt;r&#233;serve de ki&lt;/a&gt; et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#SERENITE&quot; title=&quot;Le moine&quot;&gt;s&#233;r&#233;nit&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Intuition du mystique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Intuition_du_mystique_Sur_1&quot; href=&quot;#Intuition_du_mystique_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, un mystique &lt;i&gt;ki&lt;/i&gt; devient capable de dire pr&#233;cis&#233;ment et rapidement les mots qu’il faut pour conseiller quelqu’un. Par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;, le moine peut d&#233;penser 2 points de ki pour permettre &#224; un alli&#233; situ&#233; &#224; au plus 9 m&#232;tres (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) de lui de relancer un unique &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt;. L’alli&#233; doit &#234;tre capable d’entendre le moine pour b&#233;n&#233;ficier de cette seconde chance. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#PURETEPHYSIQUE&quot; title=&quot;Le moine&quot;&gt;Puret&#233; physique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Visions du mystique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Visions_du_mystique_Sur_2&quot; href=&quot;#Visions_du_mystique_Sur_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 11, un mystique &lt;i&gt;ki&lt;/i&gt; peut recevoir des visions mystiques lorsqu’il se repose. Ces visions peuvent prendre la forme d’un r&#234;ve, d’une &#233;piphanie ou m&#234;me de la voix d’un vieil ami qui murmure &#224; l’esprit du moine.
L’effet est semblable &#224; celui d’un sort de &lt;a class=&quot;pagelink&quot; href=&quot;Divination.html&quot; title=&quot;Divination&quot;&gt;divination&lt;/a&gt; avec un &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; &#233;gal au niveau du moine. Cette divination ne n&#233;cessite aucun temps d’incantation. Elle fait tout simplement partie des r&#234;ves et visions normales qui se produisent chaque nuit. Cette capacit&#233; co&#251;te 2 points de &lt;i&gt;ki&lt;/i&gt; qui sont pr&#233;lev&#233;s dans le total de points du jour qui suit. Elle remplace Corps de diamant.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Prescience du mystique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Prescience_du_mystique_Sur_3&quot; href=&quot;#Prescience_du_mystique_Sur_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 13, le mystique &lt;i&gt;ki&lt;/i&gt; gagne un bonus d’intuition de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; et au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt;. Au niveau 20, ces bonus passent &#224; +4. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#AMEDEDIAMANT&quot; title=&quot;Le moine&quot;&gt;&#194;me de diamant&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pers&#233;v&#233;rance du mystique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Pers&#233;v&#233;rance_du_mystique_Sur_4&quot; href=&quot;#Pers&#233;v&#233;rance_du_mystique_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 19, le mystique &lt;i&gt;ki&lt;/i&gt; peut cr&#233;er une aura une fois par jour en utilisant une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; et en d&#233;pensant au moins 2 points de &lt;i&gt;ki&lt;/i&gt;. L’aura s’&#233;tend sur un &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Rayon.html&quot; title=&quot;rayon&quot;&gt;rayon&lt;/a&gt; de 6 m&#232;tres (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;). Le moine et tous ses alli&#233;s au sein de l’aura peuvent lancer deux d&#233;s pour chaque &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; et choisir le meilleur r&#233;sultat des deux. L’aura persiste pendant 1 round plus 1 round de plus par tranche de 2 points de &lt;i&gt;ki&lt;/i&gt; d&#233;pens&#233;s par le moine lors de son activation. Le moine peut supprimer l’aura &#224; n’importe quel moment par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt;, mais les points de &lt;i&gt;ki&lt;/i&gt; d&#233;pens&#233;s restent perdus. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#DESERTIONDELAME&quot; title=&quot;Le moine&quot;&gt;D&#233;sertion de l’&#226;me&lt;/a&gt;.
